from html.parser import HTMLParser
VOID = {'meta','br','hr','img','input','link','area','base','col','embed','source','track','wbr'}
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]; self.errors=[]
    def handle_starttag(self,tag,attrs):
        if tag not in VOID: self.stack.append((tag,self.getpos()))
    def handle_endtag(self,tag):
        if not self.stack: self.errors.append(f"extra </{tag}> at {self.getpos()}"); return
        top,pos=self.stack.pop()
        if top!=tag: self.errors.append(f"mismatch <{top}> at {pos} closed by </{tag}> at {self.getpos()}")
p=P()
p.feed(open('index.html',encoding='utf-8').read())
if p.stack: p.errors.append(f"unclosed: {[t for t,_ in p.stack]}")
print("OK" if not p.errors else "\n".join(p.errors))
EOF

